CREATE OR REPLACE FUNCTION public.quantidadetotaldoestoque(bigint)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
   vProduto  ALIAS FOR $1;
   vTotal    NUMERIC(11,3);

BEGIN
   SELECT sum((EmEstoque + Reservado    +
           Transito  + Demonstracao +
           Conserto  + Danificada   + ReservaPrevia)) INTO vTotal
      FROM Estoques
      WHERE Produto = vProduto;

   IF vTotal IS NULL
      THEN RETURN 0;
      ELSE RETURN vTotal;
   END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.quantidadetotaldoestoque(vproduto bigint, plistafiliais character varying)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
/*   vProduto  ALIAS FOR $1;*/
   vTotal    NUMERIC(11,3);

BEGIN
   SELECT sum((EmEstoque + Reservado    +
           Transito  + Demonstracao +
           Conserto  + Danificada   + ReservaPrevia)) INTO vTotal
      FROM Estoques
      WHERE Produto = vProduto
      
        and case when pListaFiliais<>'' then
                      filial in (select * from lista_int(cast('{'||pListaFiliais||'}' as integer[])))
                 else true     
            end;

   IF vTotal IS NULL
      THEN RETURN 0;
      ELSE RETURN vTotal;
   END IF;
END;
$function$
